<?php
require_once __DIR__.'/../includes/functions.php';student_only();$pageTitle='My applications';$s=$pdo->prepare("SELECT a.id,a.applied_at,a.status,i.title,i.company FROM applications a JOIN internships i ON i.id=a.internship_id WHERE a.student_id=? ORDER BY a.applied_at DESC");$s->execute([$_SESSION['student_id']]);$rows=$s->fetchAll();include __DIR__.'/../includes/header.php'; ?>
<h1 class="page-title">My applications</h1><div class="table-responsive panel"><table class="table align-middle mb-0"><thead><tr><th>Internship</th><th>Company</th><th>Application date</th><th>Status</th></tr></thead><tbody><?php foreach($rows as $r): ?><tr><td><?= e($r['title']) ?></td><td><?= e($r['company']) ?></td><td><?= e(date('d M Y',strtotime($r['applied_at']))) ?></td><td><span class="status"><?= e($r['status']) ?></span></td></tr><?php endforeach; ?><?php if(!$rows): ?><tr><td colspan="4" class="text-center py-4">You have not applied to any internships yet. <a href="/InternFinder/internships.php">Browse internships</a>.</td></tr><?php endif; ?></tbody></table></div>
